def proj(q, kind):
    k,n,j,m=q
    cols=[np.exp(-k*t)*A**n, t*A**2]
    if kind[0]=='exp': cols.append(np.exp(-j*t))
    elif kind[0]=='pow': cols.append(t**j)
    elif kind[0]=='tex': cols.append(t*np.exp(-j*t))
    if kind[1]=='powA': cols.append(A**m)
    elif kind[1]=='none': pass
    X=np.column_stack(cols+[np.ones_like(t)]) if kind[1]!='none' or True else None
    c,*_=np.linalg.lstsq(X,y,rcond=None)
    return np.sum((X@c-y)**2)/sst, c
